class MinStack:
    """A stack that reports its smallest value.

    Each entry of ``_items`` is paired with the minimum of the stack at the
    moment it was pushed, so popping restores the previous minimum in O(1).
    """

    def __init__(self):
        self._items = []  # list of (value, minimum_so_far) pairs

    def push(self, value):
        if self._items:
            current_min = self._items[-1][1]
            new_min = value if value < current_min else current_min
        else:
            new_min = value
        self._items.append((value, new_min))

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty MinStack")
        value, _ = self._items.pop()
        return value

    def top(self):
        if not self._items:
            raise IndexError("top from empty MinStack")
        return self._items[-1][0]

    def get_min(self):
        if not self._items:
            raise ValueError("get_min from empty MinStack")
        return self._items[-1][1]

    def __len__(self):
        return len(self._items)
